import random
perf=lambda d,p,F:(d[0],p[0]) in F
A=lambda d,P,F:all(p[1]!='Cardiac' or perf(d,p,F) for p in P)
B=lambda d,P,F:any(p[1]=='Cardiac' and perf(d,p,F) for p in P)
C=lambda d,P,F:all(p[1]=='Cardiac' and perf(d,p,F) for p in P)
D_=lambda d,P,F:all((not perf(d,p,F)) or p[1]=='Cardiac' for p in P)
want=lambda d,P,F:{p[0] for p in P if p[1]=='Cardiac'}<={y for (x,y) in F if x==d[0]}
res=lambda D,P,F,phi:sorted(d[1] for d in D if phi(d,P,F))
