def probe_sum(a):
    lo, hi = 0, len(a) - 1
    acc = 0
    while lo < hi:
        mid = (lo + hi) // 2
        acc += mid
        if a[mid] > a[hi]:
            lo = mid + 1
        else:
            hi = mid
    return acc
